//! A MIDI take through the agent tools on miniaudio's simulated device: the port of the
//! prototype's
//! `tests/agent/test_tools.py::test_start_recording_records_armed_instrument_track_from_virtual_midi`.
//!
//! `tests/fixtures/midi_take.json` is the prototype's run of the scenario, generated by
//! `scripts/golden/agent_midi_take.py` on `native-null` with a CoreMIDI virtual keyboard: arm an
//! instrument track, open the keyboard with `set_midi_input`, `start_recording` from beat 0,
//! play one note and `stop_playback`. Here the keyboard is an injected port of the same name
//! whose ring the test feeds with real arrival times (TST-08), played with the generator's
//! pauses.
//!
//! Every envelope must equal the prototype's, key order included, except the values that follow
//! the timing of the played note and of the stop: the positions of `stop_playback`, the take's
//! length, and the clip's end, length and note times in the state view. Those are checked by
//! their meaning instead, within the bounds of the application's own take test
//! (`crates/sonara-app/tests/transport.rs::live_midi_injected_records_into_clip`), which hold
//! the prototype's recorded values too.
#![cfg(unix)]

use std::fs;
use std::path::Path;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant, UNIX_EPOCH};

use serde_json::Value;
use sonara_agent::context::PolicyEnvironment;
use sonara_agent::service::{AgentOptions, AgentService, AuditTarget};
use sonara_app::clock::LocalZone;
use sonara_app::context::{AppContext, AppOptions};
use sonara_app::ids::IdSource;
use sonara_app::midi::{MidiDevices, MidiError, OpenInput};
use sonara_app::settings::Settings;
use sonara_core::ids::SequentialIds;
use sonara_rt::{MidiEvent, MidiSender, midi_channel};

/// The generator's placeholder for the sandbox root.
const ROOT: &str = "<ROOT>";
/// The generator's placeholder for wall-clock values, and this test's for timing values.
const VOLATILE: &str = "<VOLATILE>";
/// 2026-01-01T12:00:00Z, the recorder's frozen clock (`golden_common.FIXED_NOW`).
const FROZEN_UNIX_SECONDS: u64 = 1_767_268_800;

/// A keyboard whose one input the test plays: injected MIDI devices (TST-08), as in
/// `crates/sonara-app/tests/transport.rs`.
struct Keyboard {
    name: String,
    start: Instant,
    senders: Mutex<Vec<(u8, MidiSender)>>,
}

impl Keyboard {
    fn send(&self, bytes: &[u8]) {
        let time = u64::try_from(self.start.elapsed().as_micros()).expect("a short test");
        let mut senders = self.senders.lock().expect("an unpoisoned lock");
        let (port, sender) = senders.last_mut().expect("an open input");
        assert!(sender.push(MidiEvent::new(time, *port, bytes).expect("a message")));
    }
}

impl MidiDevices for Keyboard {
    fn api_name(&self) -> &'static str {
        "core"
    }

    fn input_ports(&self) -> Result<Vec<String>, MidiError> {
        Ok(vec![self.name.clone()])
    }

    fn output_ports(&self) -> Result<Vec<String>, MidiError> {
        Ok(Vec::new())
    }

    fn open_input(&self, name: &str, port: u8) -> Result<OpenInput, MidiError> {
        if name != self.name {
            return Err(MidiError::InputNotFound {
                name: name.to_owned(),
                available: vec![self.name.clone()],
            });
        }
        let (sender, events) = midi_channel(4096);
        let overflows = sender.overflows();
        self.senders
            .lock()
            .expect("an unpoisoned lock")
            .push((port, sender));
        Ok(OpenInput {
            events,
            overflows,
            connection: Box::new(()),
        })
    }

    fn open_virtual_input(&self, name: &str, _port: u8) -> Result<OpenInput, MidiError> {
        Err(MidiError::Connect {
            name: name.to_owned(),
            reason: "no virtual ports here".to_owned(),
        })
    }
}

/// The sandbox root as `<ROOT>` in every string.
fn normalize(value: &Value, root: &str) -> Value {
    match value {
        Value::String(s) => Value::String(s.replace(root, ROOT)),
        Value::Array(items) => Value::Array(items.iter().map(|v| normalize(v, root)).collect()),
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(k, v)| {
                    // The generator's wall-clock keys (`golden_batch.VOLATILE_KEYS`) that occur
                    // here: the project's `created` timestamp.
                    let v = if k == "created" && v.is_string() {
                        Value::from(VOLATILE)
                    } else {
                        normalize(v, root)
                    };
                    (k.clone(), v)
                })
                .collect(),
        ),
        other => other.clone(),
    }
}

/// `<ROOT>` back to the sandbox root in every string.
fn rooted(value: &Value, root: &str) -> Value {
    match value {
        Value::String(s) => Value::String(s.replace(ROOT, root)),
        Value::Array(items) => Value::Array(items.iter().map(|v| rooted(v, root)).collect()),
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(k, v)| (k.clone(), rooted(v, root)))
                .collect(),
        ),
        other => other.clone(),
    }
}

/// Sets the value at `pointer` to `<VOLATILE>` when it exists.
fn blank(value: &mut Value, pointer: &str) {
    if let Some(v) = value.pointer_mut(pointer) {
        *v = Value::from(VOLATILE);
    }
}

/// `value` with the values that follow the timing of the played note and the stop blanked: the
/// positions of `stop_playback` and the take's length; the song's length and content end, and
/// each clip's end, length and note times in a state view.
fn untimed(tool: &str, value: &Value) -> Value {
    let mut value = value.clone();
    match tool {
        "stop_playback" => {
            for key in ["position_beat", "position_seconds", "bar_beat"] {
                blank(&mut value, &format!("/{key}"));
            }
            if let Some(takes) = value
                .pointer_mut("/recording/takes")
                .and_then(Value::as_array_mut)
            {
                for take in takes {
                    blank(take, "/beats");
                }
            }
        }
        "get_project_state" => {
            blank(&mut value, "/state/length");
            blank(&mut value, "/state/content_end");
            let tracks = value
                .pointer_mut("/state/tracks")
                .and_then(Value::as_array_mut);
            for track in tracks.into_iter().flatten() {
                let clips = track.get_mut("clips").and_then(Value::as_array_mut);
                for clip in clips.into_iter().flatten() {
                    blank(clip, "/end");
                    blank(clip, "/length_beats");
                    let notes = clip.get_mut("notes").and_then(Value::as_array_mut);
                    for note in notes.into_iter().flatten() {
                        blank(note, "/start");
                        blank(note, "/length");
                    }
                }
            }
        }
        _ => {}
    }
    value
}

/// The first difference between two JSON values, key order included, as a JSON pointer with
/// both values. Numbers compare as JSON numbers: `1` and `1.0` differ, as they do in Python.
fn difference(expected: &Value, actual: &Value, at: &str) -> Option<String> {
    match (expected, actual) {
        (Value::Object(e), Value::Object(a)) => {
            let keys_e: Vec<&String> = e.keys().collect();
            let keys_a: Vec<&String> = a.keys().collect();
            if keys_e != keys_a {
                return Some(format!("{at}: keys {keys_e:?}, got {keys_a:?}"));
            }
            e.iter()
                .find_map(|(k, ev)| difference(ev, &a[k.as_str()], &format!("{at}/{k}")))
        }
        (Value::Array(e), Value::Array(a)) => e
            .iter()
            .zip(a)
            .enumerate()
            .find_map(|(i, (ev, av))| difference(ev, av, &format!("{at}/{i}")))
            .or_else(|| {
                (e.len() != a.len())
                    .then(|| format!("{at}: expected {} items, got {}", e.len(), a.len()))
            }),
        _ if expected == actual => None,
        _ => Some(format!("{at}: expected {expected}, got {actual}")),
    }
}

fn number(value: &Value, pointer: &str) -> f64 {
    value
        .pointer(pointer)
        .and_then(Value::as_f64)
        .unwrap_or_else(|| panic!("a number at {pointer}: {value}"))
}

fn wait_until(timeout: Duration, mut done: impl FnMut() -> bool) -> bool {
    let start = Instant::now();
    while start.elapsed() < timeout {
        if done() {
            return true;
        }
        thread::sleep(Duration::from_millis(10));
    }
    done()
}

/// The `bar:beat` text of a beat in 4/4 (`format_bar_beat` for whole beats in the first bars).
fn bar_beat(beat: f64) -> String {
    let whole = beat.floor();
    format!("{}:{}", (whole / 4.0).floor() + 1.0, whole % 4.0 + 1.0)
}

/// The application on `native-null` with the injected keyboard, and its agent service, set up
/// as the generator sets the prototype up.
struct Rig {
    _dir: tempfile::TempDir,
    root: String,
    keyboard: Arc<Keyboard>,
    app: Arc<AppContext>,
    service: AgentService,
}

impl Rig {
    fn new(port: &str, lookahead_ms: f64) -> Self {
        let dir = tempfile::Builder::new()
            .prefix("sonara-golden-")
            .tempdir()
            .expect("a sandbox");
        let root = fs::canonicalize(dir.path()).expect("the sandbox resolves");
        for sub in ["home", "projects", "work", "workspaces"] {
            fs::create_dir(root.join(sub)).expect("a sandbox folder");
        }
        let keyboard = Arc::new(Keyboard {
            name: port.to_owned(),
            start: Instant::now(),
            senders: Mutex::new(Vec::new()),
        });
        let mut settings = Settings::default();
        settings.audio.lookahead_ms = lookahead_ms;
        let app = Arc::new(
            AppContext::create(AppOptions {
                workspaces: Some(root.join("workspaces")),
                settings: Some(settings),
                persist_settings: false,
                audio_backend: Some("native-null".to_owned()),
                ids: Some(IdSource::new(Box::new(SequentialIds::new(0)))),
                wall_clock: Some(Arc::new(|| {
                    UNIX_EPOCH + Duration::from_secs(FROZEN_UNIX_SECONDS)
                })),
                local_zone: LocalZone::Utc,
                undo_clock: Some(Arc::new(|| 0.0)),
                midi_devices: Some(Arc::clone(&keyboard) as Arc<dyn MidiDevices>),
                ..AppOptions::default()
            })
            .expect("the application"),
        );
        let counter = Arc::new(AtomicU64::new(0));
        let service = AgentService::new(
            Arc::clone(&app),
            AgentOptions {
                base_dir: Some(root.join("work")),
                audit: AuditTarget::Disabled,
                allowed_paths: vec![root.clone()],
                tokens: Some(Arc::new(move || {
                    // Orders tokens only.
                    let n = counter.fetch_add(1, Ordering::Relaxed) + 1;
                    format!("golden-token-{n:04}")
                })),
                environment: Some(PolicyEnvironment {
                    allowed: None,
                    projects_dir: root.join("projects"),
                }),
                ..AgentOptions::default()
            },
        )
        .expect("the agent service");
        Self {
            _dir: dir,
            root: root.to_str().expect("a UTF-8 sandbox").to_owned(),
            keyboard,
            app,
            service,
        }
    }

    /// The generator's pauses around the note, then the note's two messages delivered.
    fn play(&self, pitch: u8, velocity: u8) {
        thread::sleep(Duration::from_millis(300));
        self.keyboard.send(&[0x90, pitch, velocity]);
        thread::sleep(Duration::from_millis(200));
        self.keyboard.send(&[0x80, pitch, 0]);
        thread::sleep(Duration::from_millis(200));
        assert!(
            wait_until(Duration::from_secs(5), || {
                self.app.transport().midi_status()["messages_received"]
                    .as_u64()
                    .is_some_and(|n| n >= 2)
            }),
            "the note's messages arrive"
        );
    }
}

/// The values [`untimed`] blanks, by their meaning: `who` stopped with `stopped` and then
/// reported `state`.
fn check_timing(who: &str, stopped: &Value, state: &Value) {
    let beat = number(stopped, "/position_beat");
    let seconds = number(stopped, "/position_seconds");
    // 120 BPM, both rounded to 4 decimals; the stop comes after the 0.7 s of pauses, less the
    // device latency.
    assert!((beat - 2.0 * seconds).abs() < 2e-4, "{who}: {stopped}");
    assert!(0.5 < seconds && seconds < 5.0, "{who}: {stopped}");
    assert_eq!(stopped["bar_beat"], bar_beat(beat).as_str(), "{who}");
    // The take's length in beats, rounded to 3 decimals in the take summary; the clip starts at
    // 0, so it ends there, as does the song.
    let clip = &state["state"]["tracks"][0]["clips"][0];
    let length = number(clip, "/length_beats");
    let take = number(stopped, "/recording/takes/0/beats");
    assert!(
        (take - length).abs() <= 5e-4,
        "{who}: take {take}, clip {length}"
    );
    assert_eq!(number(clip, "/end/beat"), length, "{who}");
    assert_eq!(number(state, "/state/content_end/beat"), length, "{who}");
    assert_eq!(number(state, "/state/length/beat"), length, "{who}");
    // Seconds are rounded to 4 decimals in the state view.
    let end_seconds = number(clip, "/end/seconds");
    assert!(
        (end_seconds - length / 2.0).abs() <= 1e-4,
        "{who}: {end_seconds}"
    );
    assert_eq!(clip["end"]["bar_beat"], bar_beat(length).as_str(), "{who}");
    // The note was played about 0.3 s (0.6 beats) after the start and held about 0.2 s.
    let note = &clip["notes"][0];
    let start = number(note, "/start");
    let held = number(note, "/length");
    assert!(0.2 < start && start < 1.2, "{who}: start {start}");
    assert!(0.2 < held && held < 1.0, "{who}: length {held}");
    assert!(start + held <= length, "{who}: the take holds the note");
}

/// T2: the armed "Pluck" track records the keyboard's G4 into a take clip through the tools,
/// with every envelope the prototype's.
#[test]
fn start_recording_records_armed_instrument_track_from_virtual_midi() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/midi_take.json");
    let fixture: Value =
        serde_json::from_slice(&fs::read(&path).expect("the fixture")).expect("fixture JSON");
    let steps = fixture["steps"].as_array().expect("the recorded steps");
    let tools: Vec<&str> = steps
        .iter()
        .map(|s| s["tool"].as_str().expect("a tool"))
        .collect();
    assert_eq!(
        tools,
        [
            "create_project",
            "create_track",
            "set_track_state",
            "set_midi_input",
            "list_midi_devices",
            "set_midi_input",
            "list_midi_devices",
            "start_recording",
            "stop_playback",
            "get_project_state"
        ]
    );
    let pitch = u8::try_from(fixture["note"]["pitch"].as_u64().expect("a pitch")).expect("7 bits");
    let velocity =
        u8::try_from(fixture["note"]["velocity"].as_u64().expect("a velocity")).expect("7 bits");
    let rig = Rig::new(
        fixture["port"].as_str().expect("the port"),
        fixture["lookahead_ms"].as_f64().expect("the lookahead"),
    );

    let mut failures = Vec::new();
    let mut actual = Vec::new();
    for (i, step) in steps.iter().enumerate() {
        let tool = tools[i];
        if tool == "stop_playback" {
            rig.play(pitch, velocity);
        }
        let args = rooted(&step["args"], &rig.root);
        let result = normalize(&rig.service.call(tool, Some(&args)), &rig.root);
        if let Some(d) = difference(&untimed(tool, &step["result"]), &untimed(tool, &result), "") {
            failures.push(format!("step {i} ({tool}): {d}"));
        }
        actual.push(result);
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
    // The blanked values, by their meaning, in the recording and here.
    check_timing("prototype", &steps[8]["result"], &steps[9]["result"]);
    check_timing("rust", &actual[8], &actual[9]);
}
